def find_bbox(color, grid, H=h, W=w):
    min_r, max_r = H, -1
    min_c, max_c = W, -1
    for r in range(H):
        for c in range(W):
            if grid[r][c] == color:
                min_r, max_r = min(min_r, r), max(max_r, r)
                min_c, max_c = min(min_c, c), max(max_c, c)
    return (min_r, min_c, max_r, max_c) if (min_r <= max_r and min_c <= max_c) else None

