def find_rectangular_frames(grid):
    visited = [[False]*len(grid[0]) for _ in range(len(grid))]
    frames = []

    for sr in range(h):
        for sc in range(w):
            if visited[sr][sc] or grid[sr][sc] == bg_color:
                continue

            color = grid[sr][sc]
            queue = [(sr, sc)]
