            cells = set()

            while queue:
                r, c = queue.pop(0)
                cells.add((r,c))
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc]:
                        if grid[nr][nc] == color:
