                            queue.append((nr, nc))
                            cells.add((nr, nc))

            # Determine bounding box
            rmin = min(c[0] for c in cells)
            cmin = min(c[1] for c in cells)
            rmax = max(c[0] for c in cells)
            cmax = max(c[1] for c in cells)

            # Check if this is a rectangle frame 
            interior_colors = set()
            for r in range(rmin+1, rmax):
                for c in range(cmin+1, cmax):
                    if grid[r][c] != bg_color:
                        interior_colors.add(grid[r][c])

