        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

test_in = G['Test input']
h, w = len(test_in), len(test_in[0])
bg_color = test_in[0][0]

# Find all hollow frames in test input
visited = [[False]*w for _ in range(h)]
frames = []

for sr in range(h):
    for sc in range(w):
        if visited[sr][sc] or test_in[sr][sc] == bg_color:
            continue

        color = test_in[sr][sc]
        queue = [(sr, sc)]
        visited[sr][sc] = True
        comp_cells = set()

        while queue:
            r, c = queue.pop(0)
            comp_cells.add((r,c))
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc]:
                    if test_in[nr][nc] == color:
                        visited[nr][nc] = True
                        queue.append((nr, nc))
                        comp_cells.add((nr, nc))

        # Calculate bbox
        rmin, cmin, rmax, cmax = min(c[0] for c in comp_cells), min(c[1] for c in comp_cells), max(c[0] for c in comp_cells), max(c[1] for c in comp_cells)

        # Check if hollow (interior contains only background)
        is_hollow = True
        for r in range(rmin+1, rmax):
            for c in range(cmin+1, cmax):
                if test_in[r][c] != bg_color:
                    is_hollow = False
                    break
            if not is_hollow:
                break

        if is_hollow:
            frames.append({
                'idx': len(frames)-1,
                'color': color,
                'bbox': (rmin, cmin, rmax, cmax),
            })

print(f"Found {len(frames)} hollow frames")
sorted_frames = sorted(frames, key=lambda x: (x['bbox'][0], x['bbox'][1]))
for i, f in enumerate(sorted_frames):
    print(f"  Frame order {i}: color={f['color']}, bbox={f['bbox']}")

# Apply fill pattern based on processing order
result = [row[:] for row in test_in]
fill_colors = [7, 7, 7, 2]  # indices 0,1,2 -> 7; index 3 -> 2

for i, f in enumerate(sorted_frames):
    rmin, cmin, rmax, cmax = f['bbox']
    fill_color = fill_colors[i]
    for r in range(rmin+1, rmax):
        for c in range(cmin+1, cmax):
            if result[r][c] == bg_color:
                result[r][c] = fill_color

print("\nResult visualization:")
for r in range(h):
    row_str = ' '.join(str(result[r][c]) for c in range(w))
    print(row_str)

print(f"\n\nJSON submission:\n{json.dumps(result)}")

